import es from "./i18n/es.json";
import fr from "./i18n/fr.json";
import hi from "./i18n/hi.json";
import ko from "./i18n/ko.json";
import vi from "./i18n/vi.json";
import zh from "./i18n/zh.json";
import type { LangId } from "./lang";

/**
 * Whole-app translation. Every string on screen goes through t("English text", { vars }).
 * The English text is the key; lib/i18n/<lang>.json holds the translations, generated by
 * `npm run i18n` and checked by lib/i18n.test.ts so no string is ever missing.
 * Dish names, hall names and dorm names are never translated (they're how USC writes them).
 */
export type Vars = Record<string, string | number>;
export type T = (en: string, vars?: Vars) => string;

export const DICTS: Record<Exclude<LangId, "en">, Record<string, string>> = { es, fr, zh, ko, hi, vi };

const fill = (s: string, vars?: Vars) => (vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s);

export function translate(lang: LangId | undefined, en: string, vars?: Vars): string {
  const dict = lang && lang !== "en" ? DICTS[lang] : undefined;
  return fill(dict?.[en] || en, vars);
}

export const makeT =
  (lang: LangId | undefined): T =>
  (en, vars) =>
    translate(lang, en, vars);
